package local.proxy.switcher;
import android.app.Activity; import android.os.Bundle; import android.provider.Settings; import android.graphics.Color; import android.view.Gravity; import android.widget.*; import java.util.ArrayList;
public class MainActivity extends Activity {
  LinearLayout root; TextView status,address,indicator; android.content.SharedPreferences prefs; boolean en; ArrayList<Button> uses=new ArrayList<>(); ArrayList<String> keys=new ArrayList<>();
  String t(String zh,String enText){return en?enText:zh;} int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} TextView text(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(dp(12),dp(8),dp(12),dp(8));return v;}
  void focus(Button b){b.setOnFocusChangeListener((v,f)->{b.setBackgroundColor(f?Color.rgb(255,193,7):Color.rgb(100,100,100));b.setTextColor(f?Color.BLACK:Color.WHITE);});}
  public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("presets",0);en=prefs.getBoolean("english",false);build();refresh();}
  void build(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(48),dp(28),dp(48),dp(28));root.setBackgroundColor(Color.rgb(20,20,20));LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);TextView title=text(t("电视代理控制","TV Proxy Control"),28);indicator=text("●",38);Button lang=new Button(this);lang.setText(en?"切换中文显示":"Switch to English");lang.setOnClickListener(v->{prefs.edit().putBoolean("english",!en).apply();en=!en;build();refresh();});head.addView(title,new LinearLayout.LayoutParams(0,dp(64),1));head.addView(lang,new LinearLayout.LayoutParams(dp(220),dp(64)));head.addView(indicator,new LinearLayout.LayoutParams(dp(90),dp(64)));root.addView(head,new LinearLayout.LayoutParams(-1,dp(70)));status=text("",22);Button off=new Button(this);off.setText(t("关闭代理","Disable Proxy"));focus(off);off.setOnClickListener(v->setProxy(":0"));LinearLayout sr=new LinearLayout(this);sr.addView(status,new LinearLayout.LayoutParams(0,dp(62),1));sr.addView(off,new LinearLayout.LayoutParams(dp(210),dp(62)));root.addView(sr);address=text(t("HTTP代理清单：","HTTP Proxy List: "),20);root.addView(address);uses.clear();keys.clear();for(int i=0;i<4;i++)addPreset(i);setContentView(root);}
  void addPreset(int i){LinearLayout row=new LinearLayout(this);EditText n=new EditText(this);n.setText(prefs.getString("name"+i,""));n.setHint(t("设备备注","Device name"));EditText h=new EditText(this);h.setText(prefs.getString("host"+i,i==0?"192.168.3.11":""));h.setHint("IP");EditText p=new EditText(this);p.setText(prefs.getString("port"+i,i==0?"1082":""));p.setHint(t("端口","Port"));p.setInputType(2);Button save=new Button(this);save.setText(t("保存","Save"));Button use=new Button(this);use.setText(t("使用","Use"));focus(save);focus(use);uses.add(use);keys.add(h.getText().toString()+":"+p.getText().toString());Runnable saveIt=()->{String host=h.getText().toString().trim().replace('·','.').replace('．','.').replace('。','.');prefs.edit().putString("name"+i,n.getText().toString().trim()).putString("host"+i,host).putString("port"+i,p.getText().toString().trim()).apply();keys.set(i,host+":"+p.getText().toString().trim());refresh();Toast.makeText(this,t("已保存","Saved"),Toast.LENGTH_SHORT).show();};save.setOnClickListener(v->saveIt.run());use.setOnClickListener(v->{saveIt.run();setProxy(h.getText().toString().trim()+":"+p.getText().toString().trim());});row.addView(n,new LinearLayout.LayoutParams(0,dp(62),1.2f));row.addView(h,new LinearLayout.LayoutParams(0,dp(62),1.8f));row.addView(p,new LinearLayout.LayoutParams(0,dp(62),.9f));row.addView(save,new LinearLayout.LayoutParams(dp(125),dp(62)));row.addView(use,new LinearLayout.LayoutParams(dp(125),dp(62)));root.addView(row);}
  String proxy(){return Settings.Global.getString(getContentResolver(),"http_proxy");} void refresh(){String p=proxy();boolean on=p!=null&&!p.isEmpty()&&!p.equals(":0")&&!p.equals("null");String label="";if(on){for(int i=0;i<4;i++){String k=prefs.getString("host"+i,"")+":"+prefs.getString("port"+i,"");if(k.equals(p)){label=prefs.getString("name"+i,"");break;}}}indicator.setTextColor(on?Color.rgb(60,210,80):Color.rgb(230,55,55));status.setText(on?(label.isEmpty()?t("状态：已启用（","Status: Enabled ("):t("正在使用：","Using: ")+label+"（")+p+"）":t("状态：未启用","Status: Disabled"));address.setText(t("HTTP代理清单：","HTTP Proxy List: ")+((on)?p:t("未设置","Not set")));for(Button b:uses)b.setText(t("使用","Use"));}
  void setProxy(String p){try{Settings.Global.putString(getContentResolver(),"http_proxy",p);Settings.Global.putString(getContentResolver(),"global_http_proxy_host",p.equals(":0")?"":p.substring(0,p.lastIndexOf(':')));Settings.Global.putString(getContentResolver(),"global_http_proxy_port",p.equals(":0")?"0":p.substring(p.lastIndexOf(':')+1));refresh();}catch(Exception e){Toast.makeText(this,t("权限不足","Permission denied"),Toast.LENGTH_LONG).show();}}
}
